#include "pde.hpp"
#include <vector>
#include <algorithm>
#include <cmath>
#include <stdexcept>

namespace model {

// Helper function to compute payoff
double payoff(Kind kind, double S, double K) {
    switch (kind) {
        case Kind::EuropeanCall:
            return std::max(S - K, 0.0);
        case Kind::EuropeanPut:
            return std::max(K - S, 0.0);
        case Kind::AmericanPut:
            return std::max(K - S, 0.0);
        case Kind::DigitalCall:
            return (S > K) ? 1.0 : 0.0;
        default:
            return 0.0;
    }
}

// Helper function to compute the grid points in log-space
std::vector<double> create_log_grid(double S_min, double S_max, int nS) {
    std::vector<double> grid(nS + 1);
    double log_S_min = std::log(S_min);
    double log_S_max = std::log(S_max);
    double dlog = (log_S_max - log_S_min) / nS;
    for (int i = 0; i <= nS; ++i) {
        grid[i] = std::exp(log_S_min + i * dlog);
    }
    return grid;
}

// Helper function to compute the grid points in log-space for the PDE
std::vector<double> create_log_grid_pde(double S_min, double S_max, int nS) {
    std::vector<double> grid(nS + 1);
    double log_S_min = std::log(S_min);
    double log_S_max = std::log(S_max);
    double dlog = (log_S_max - log_S_min) / nS;
    for (int i = 0; i <= nS; ++i) {
        grid[i] = log_S_min + i * dlog;
    }
    return grid;
}

// Helper function to compute the grid points in log-space for the PDE
std::vector<double> create_log_grid_pde_spot(double S_min, double S_max, int nS) {
    std::vector<double> grid(nS + 1);
    double log_S_min = std::log(S_min);
    double log_S_max = std::log(S_max);
    double dlog = (log_S_max - log_S_min) / nS;
    for (int i = 0; i <= nS; ++i) {
        grid[i] = std::exp(log_S_min + i * dlog);
    }
    return grid;
}

PdeResult pde_price(Kind kind, double S, double K, double r, double q, double sigma, double T, int nS, int nT) {
    // Set up the grid parameters
    const double S_min = 1e-6;  // Minimum spot value
    const double S_max = 1e6;   // Maximum spot value

    // Create log grid for the PDE
    std::vector<double> log_grid = create_log_grid_pde(S_min, S_max, nS);
    std::vector<double> spot_grid = create_log_grid_pde_spot(S_min, S_max, nS);

    // Convert spot to log-space
    double log_S = std::log(S);

    // Compute grid spacing
    double dlog = log_grid[1] - log_grid[0];
    double dS = spot_grid[1] - spot_grid[0];

    // Time step
    double dt = T / nT;

    // Compute the coefficients for the Crank-Nicolson scheme
    double alpha = 0.5 * sigma * sigma * dt / (dlog * dlog);
    double beta = 0.5 * dt * (r - q) / dlog;

    // Create the coefficient matrices for Crank-Nicolson
    std::vector<double> a(nS + 1, 0.0);
    std::vector<double> b(nS + 1, 0.0);
    std::vector<double> c(nS + 1, 0.0);

    // Fill the coefficient vectors
    for (int i = 1; i < nS; ++i) {
        a[i] = -alpha - 0.5 * beta;
        b[i] = 1.0 + 2.0 * alpha;
        c[i] = -alpha + 0.5 * beta;
    }

    // Boundary conditions
    a[0] = 0.0;
    b[0] = 1.0;
    c[0] = 0.0;

    a[nS] = 0.0;
    b[nS] = 1.0;
    c[nS] = 0.0;

    // Initialize the option values at maturity
    std::vector<double> V(nS + 1, 0.0);
    for (int i = 0; i <= nS; ++i) {
        V[i] = payoff(kind, spot_grid[i], K);
    }

    // For American options, we need to handle early exercise
    bool is_american = (kind == Kind::AmericanPut);

    // Time-stepping loop (backward in time)
    for (int j = nT - 1; j >= 0; --j) {
        // For American options, we need to check early exercise at each time step
        if (is_american) {
            // Create temporary vectors for the tridiagonal system
            std::vector<double> d(nS + 1, 0.0);
            std::vector<double> u(nS + 1, 0.0);
            std::vector<double> v(nS + 1, 0.0);

            // Set up the tridiagonal system for Crank-Nicolson
            for (int i = 1; i < nS; ++i) {
                d[i] = V[i] + alpha * (V[i+1] - 2.0 * V[i] + V[i-1]) + 
                       0.5 * dt * (r - q) * (V[i+1] - V[i-1]) / (2.0 * dlog);
            }

            // Apply boundary conditions
            d[0] = 0.0;
            d[nS] = 0.0;

            // Solve the tridiagonal system using Thomas algorithm
            // Forward elimination
            u[1] = c[1] / b[1];
            v[1] = d[1] / b[1];
            for (int i = 2; i < nS; ++i) {
                double denom = b[i] - a[i] * u[i-1];
                u[i] = c[i] / denom;
                v[i] = (d[i] - a[i] * v[i-1]) / denom;
            }

            // Backward substitution
            V[nS] = 0.0;  // Boundary condition
            for (int i = nS - 1; i >= 0; --i) {
                V[i] = v[i] - u[i] * V[i+1];
            }

            // Apply early exercise condition for American put
            for (int i = 0; i <= nS; ++i) {
                double exercise_value = payoff(kind, spot_grid[i], K);
                V[i] = std::max(V[i], exercise_value);
            }
        } else {
            // For European options, just solve the tridiagonal system
            std::vector<double> d(nS + 1, 0.0);
            std::vector<double> u(nS + 1, 0.0);
            std::vector<double> v(nS + 1, 0.0);

            // Set up the tridiagonal system for Crank-Nicolson
            for (int i = 1; i < nS; ++i) {
                d[i] = V[i] + alpha * (V[i+1] - 2.0 * V[i] + V[i-1]) + 
                       0.5 * dt * (r - q) * (V[i+1] - V[i-1]) / (2.0 * dlog);
            }

            // Apply boundary conditions
            d[0] = 0.0;
            d[nS] = 0.0;

            // Solve the tridiagonal system using Thomas algorithm
            // Forward elimination
            u[1] = c[1] / b[1];
            v[1] = d[1] / b[1];
            for (int i = 2; i < nS; ++i) {
                double denom = b[i] - a[i] * u[i-1];
                u[i] = c[i] / denom;
                v[i] = (d[i] - a[i] * v[i-1]) / denom;
            }

            // Backward substitution
            V[nS] = 0.0;  // Boundary condition
            for (int i = nS - 1; i >= 0; --i) {
                V[i] = v[i] - u[i] * V[i+1];
            }
        }
    }

    // Interpolate to get the value at the requested spot
    int i = 0;
    while (i < nS && spot_grid[i] < S) {
        ++i;
    }

    double value = 0.0;
    double delta = 0.0;
    double gamma = 0.0;

    if (i == 0) {
        // S is below the first grid point
        value = V[0];
        delta = 0.0;
        gamma = 0.0;
    } else if (i == nS) {
        // S is above the last grid point
        value = V[nS];
        delta = 0.0;
        gamma = 0.0;
    } else {
        // Interpolate between grid points
        double S1 = spot_grid[i-1];
        double S2 = spot_grid[i];
        double V1 = V[i-1];
        double V2 = V[i];

        double ratio = (S - S1) / (S2 - S1);
        value = V1 + ratio * (V2 - V1);

        // Compute delta and gamma using finite differences
        if (i > 0 && i < nS) {
            double dS1 = S - S1;
            double dS2 = S2 - S;
            delta = (V2 - V1) / (S2 - S1);
            gamma = (V2 - 2.0 * value + V1) / (dS1 * dS2);
        }
    }

    return {value, delta, gamma};
}

}  // namespace model

