        if (i > 0 && i < nS) {
            double dS1 = S - S1;
            double dS2 = S2 - S;
            delta = (V2 - V1) / (S2 - S1);
            gamma = (V2 - 2.0 * value + V1) / (dS1 * dS2);
        }
    }

    return {value, delta, gamma};
}

}  // namespace model

